# domain/services.py - stateless: no instance, no class needed
from typing import Protocol

class ExchangeRates(Protocol):          # structural port owned by the domain
    def rate_for(self, frm: Currency, to: Currency) -> Decimal: ...

def convert(amount: Money, target: Currency, *, rates: ExchangeRates) -> Money:
    return amount.times(rates.rate_for(amount.currency, target)).in_(target)
